-- Read-only staging schema snapshot for isolated Postgres tests; no user data.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth; create schema private; create schema storage;
create table auth.users(id uuid primary key,email text,email_confirmed_at timestamptz);
create function auth.uid() returns uuid language sql stable as $$ select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid; $$;
create function auth.role() returns text language sql stable as $$ select nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'; $$;
grant usage on schema auth,private,public,storage to anon,authenticated,service_role;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text);
alter table storage.objects enable row level security;
create table public.tenants(id uuid not null default gen_random_uuid(), business_name text not null, tenant_slug text not null, primary_domain text, status text not null default 'SETUP'::text, timezone text not null default 'America/Los_Angeles'::text, plan_code text, metadata jsonb not null default '{}'::jsonb, activated_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id), CHECK (((primary_domain IS NULL) OR ((primary_domain = lower(primary_domain)) AND (primary_domain !~ '://'::text) AND (primary_domain !~ '/'::text) AND (primary_domain ~ '^([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'::text)))), UNIQUE (primary_domain), CHECK (((tenant_slug = lower(tenant_slug)) AND (tenant_slug ~ '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$'::text))), CHECK ((tenant_slug <> ALL (ARRAY['www'::text, 'app'::text, 'admin'::text, 'api'::text, 'status'::text, 'help'::text, 'support'::text, 'billing'::text, 'login'::text, 'auth'::text, 'dev'::text, 'staging'::text, 'prod'::text, 'production'::text, 'mail'::text, 'smtp'::text, 'ftp'::text, 'cdn'::text, 'assets'::text]))), CHECK ((status = ANY (ARRAY['SETUP'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'CANCELLED'::text]))), UNIQUE (tenant_slug));
alter table public.tenants enable row level security;
grant select,insert,update,delete on public.tenants to authenticated,service_role;
create table public.tenant_users(id uuid not null default gen_random_uuid(), tenant_id uuid not null, user_id uuid, invited_email text, role text not null default 'VIEWER'::text, status text not null default 'ACTIVE'::text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), CHECK (((user_id IS NOT NULL) OR (NULLIF(btrim(invited_email), ''::text) IS NOT NULL))), PRIMARY KEY (id), CHECK ((role = ANY (ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text, 'VIEWER'::text]))), CHECK ((status = ANY (ARRAY['INVITED'::text, 'ACTIVE'::text, 'DISABLED'::text]))));
alter table public.tenant_users enable row level security;
grant select,insert,update,delete on public.tenant_users to authenticated,service_role;
create table public.audit_log(id bigint not null generated by default as identity, tenant_id uuid, actor_user_id uuid, action text not null, entity_type text, entity_id text, details jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), PRIMARY KEY (id));
alter table public.audit_log enable row level security;
grant select,insert,update,delete on public.audit_log to authenticated,service_role;
create table public.platform_admins(id uuid not null default gen_random_uuid(), user_id uuid not null, role text not null, status text not null default 'ACTIVE'::text, display_name text, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id), CHECK ((role = ANY (ARRAY['PLATFORM_OWNER'::text, 'PLATFORM_ADMIN'::text, 'PLATFORM_OPERATOR'::text, 'PLATFORM_SUPPORT'::text]))), CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text]))), UNIQUE (user_id));
alter table public.platform_admins enable row level security;
grant select,insert,update,delete on public.platform_admins to authenticated,service_role;
create table public.automation_tasks(id uuid not null default gen_random_uuid(), tenant_id uuid, workflow_id uuid, onboarding_step_id uuid, task_code text not null, task_name text not null, task_type text not null, status text not null default 'PENDING'::text, priority smallint not null default 100, scheduled_for timestamp with time zone, locked_at timestamp with time zone, locked_by text, retry_count integer not null default 0, max_retries integer not null default 3, requires_intervention boolean not null default false, intervention_reason text, payload jsonb not null default '{}'::jsonb, last_error text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), CHECK ((max_retries >= 0)), PRIMARY KEY (id), CHECK (((priority >= 1) AND (priority <= 999))), CHECK ((retry_count >= 0)), CHECK ((status = ANY (ARRAY['PENDING'::text, 'READY'::text, 'RUNNING'::text, 'BLOCKED'::text, 'COMPLETE'::text, 'FAILED'::text, 'CANCELLED'::text]))), CHECK ((task_type = ANY (ARRAY['AUTOMATIC'::text, 'APPROVAL'::text, 'MANUAL'::text, 'MONITOR'::text]))));
alter table public.automation_tasks enable row level security;
grant select,insert,update,delete on public.automation_tasks to authenticated,service_role;
create table public.automation_runs(id uuid not null default gen_random_uuid(), task_id uuid, tenant_id uuid, workflow_id uuid, automation_name text not null, status text not null, attempt_number integer not null default 1, started_at timestamp with time zone not null default now(), completed_at timestamp with time zone, input_payload jsonb not null default '{}'::jsonb, output_payload jsonb not null default '{}'::jsonb, error_code text, error_message text, requires_intervention boolean not null default false, created_at timestamp with time zone not null default now(), CHECK ((attempt_number > 0)), PRIMARY KEY (id), CHECK ((status = ANY (ARRAY['RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text]))));
alter table public.automation_runs enable row level security;
grant select,insert,update,delete on public.automation_runs to authenticated,service_role;
create table public.ai4cc_contacts(id uuid not null default gen_random_uuid(), tenant_id uuid not null, first_name text, last_name text, display_name text, company_name text, email text, phone text, preferred_channel text, lead_source text, lead_score integer not null default 0, priority text not null default 'normal'::text, sms_consent boolean not null default false, email_consent boolean not null default false, do_not_contact boolean not null default false, tags text[] not null default '{}'::text[], metadata jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), CHECK (((lead_score >= 0) AND (lead_score <= 100))), PRIMARY KEY (id), CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))));
alter table public.ai4cc_contacts enable row level security;
grant select,insert,update,delete on public.ai4cc_contacts to authenticated,service_role;
create table public.ai4cc_interactions(id uuid not null default gen_random_uuid(), tenant_id uuid not null, channel text not null, direction text not null default 'inbound'::text, external_id text, customer_identifier text, queue_id uuid, agent_id uuid, flow_version_id uuid, status text not null default 'open'::text, started_at timestamp with time zone not null default now(), ended_at timestamp with time zone, metadata jsonb not null default '{}'::jsonb, CHECK ((channel = ANY (ARRAY['voice'::text, 'chat'::text, 'email'::text, 'sms'::text, 'social'::text, 'simulation'::text]))), CHECK ((direction = ANY (ARRAY['inbound'::text, 'outbound'::text, 'internal'::text]))), PRIMARY KEY (id), CHECK ((status = ANY (ARRAY['open'::text, 'queued'::text, 'active'::text, 'completed'::text, 'abandoned'::text, 'failed'::text]))), UNIQUE (tenant_id, channel, external_id));
alter table public.ai4cc_interactions enable row level security;
grant select,insert,update,delete on public.ai4cc_interactions to authenticated,service_role;
create table public.ai4cc_leads(id uuid not null default gen_random_uuid(), tenant_id uuid not null, contact_id uuid not null, originating_interaction_id uuid, originating_channel text, originating_queue_id uuid, originating_agent_id uuid, title text not null, service_interest text, description text, pipeline_stage text not null default 'new'::text, status text not null default 'open'::text, priority text not null default 'normal'::text, score integer not null default 0, estimated_value numeric(14,2) not null default 0, probability integer not null default 0, expected_close_date date, assigned_agent_id uuid, next_action text, next_follow_up timestamp with time zone, last_contacted_at timestamp with time zone, converted_at timestamp with time zone, lost_reason text, metadata jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), CHECK ((pipeline_stage = ANY (ARRAY['new'::text, 'qualified'::text, 'contacted'::text, 'follow_up'::text, 'opportunity'::text, 'converted'::text, 'lost'::text, 'nurture'::text]))), PRIMARY KEY (id), CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))), CHECK (((probability >= 0) AND (probability <= 100))), CHECK (((score >= 0) AND (score <= 100))), CHECK ((status = ANY (ARRAY['open'::text, 'won'::text, 'lost'::text, 'closed'::text]))));
alter table public.ai4cc_leads enable row level security;
grant select,insert,update,delete on public.ai4cc_leads to authenticated,service_role;
create table public.ai4cc_transcripts(id uuid not null default gen_random_uuid(), tenant_id uuid not null, interaction_id uuid not null, speaker text, sequence_no integer not null default 0, content text not null, started_at timestamp with time zone, ended_at timestamp with time zone, sentiment numeric, metadata jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), PRIMARY KEY (id));
alter table public.ai4cc_transcripts enable row level security;
grant select,insert,update,delete on public.ai4cc_transcripts to authenticated,service_role;
grant usage,select on all sequences in schema public to authenticated,service_role;
create function private.is_tenant_member(t uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.tenant_users where tenant_id=t and user_id=auth.uid() and status='ACTIVE'); $$;
create function private.has_tenant_role(t uuid,roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.tenant_users where tenant_id=t and user_id=auth.uid() and status='ACTIVE' and role=any(roles)); $$;
create function private.is_platform_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.platform_admins where user_id=auth.uid() and status='ACTIVE'); $$;
create function private.has_platform_role(roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.platform_admins where user_id=auth.uid() and status='ACTIVE' and role=any(roles)); $$;
create policy ai4cc_contacts_member_delete on public.ai4cc_contacts for DELETE to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text]));
create policy ai4cc_contacts_member_insert on public.ai4cc_contacts for INSERT to authenticated with check (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text]));
create policy ai4cc_contacts_member_select on public.ai4cc_contacts for SELECT to authenticated using (private.is_tenant_member(tenant_id));
create policy ai4cc_contacts_member_update on public.ai4cc_contacts for UPDATE to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text])) with check (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text]));
create policy ai4cc_interactions_member_select on public.ai4cc_interactions for SELECT to authenticated using (private.is_tenant_member(tenant_id));
create policy ai4cc_leads_member_delete on public.ai4cc_leads for DELETE to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text]));
create policy ai4cc_leads_member_insert on public.ai4cc_leads for INSERT to authenticated with check (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text]));
create policy ai4cc_leads_member_select on public.ai4cc_leads for SELECT to authenticated using (private.is_tenant_member(tenant_id));
create policy ai4cc_leads_member_update on public.ai4cc_leads for UPDATE to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text])) with check (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text, 'MANAGER'::text, 'AGENT'::text]));
create policy ai4cc_transcripts_member_select on public.ai4cc_transcripts for SELECT to authenticated using (private.is_tenant_member(tenant_id));
create policy audit_log_select_admin on public.audit_log for SELECT to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text]));
create policy automation_runs_platform_read on public.automation_runs for SELECT to authenticated using (private.is_platform_admin());
create policy automation_tasks_platform_access on public.automation_tasks for ALL to authenticated using (private.is_platform_admin()) with check (private.is_platform_admin());
create policy platform_admins_delete_owner on public.platform_admins for DELETE to authenticated using (private.has_platform_role(ARRAY['PLATFORM_OWNER'::text]));
create policy platform_admins_insert_owner on public.platform_admins for INSERT to authenticated with check (private.has_platform_role(ARRAY['PLATFORM_OWNER'::text]));
create policy platform_admins_select_self_or_owner on public.platform_admins for SELECT to authenticated using (((user_id = ( SELECT auth.uid() AS uid)) OR private.has_platform_role(ARRAY['PLATFORM_OWNER'::text])));
create policy platform_admins_update_owner on public.platform_admins for UPDATE to authenticated using (private.has_platform_role(ARRAY['PLATFORM_OWNER'::text])) with check (private.has_platform_role(ARRAY['PLATFORM_OWNER'::text]));
create policy tenant_users_delete_admin on public.tenant_users for DELETE to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text]));
create policy tenant_users_insert_admin on public.tenant_users for INSERT to authenticated with check (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text]));
create policy tenant_users_select_member on public.tenant_users for SELECT to authenticated using (private.is_tenant_member(tenant_id));
create policy tenant_users_update_admin on public.tenant_users for UPDATE to authenticated using (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text])) with check (private.has_tenant_role(tenant_id, ARRAY['OWNER'::text, 'ADMIN'::text]));
create policy tenants_select_member on public.tenants for SELECT to authenticated using (private.is_tenant_member(id));
create policy tenants_update_admin on public.tenants for UPDATE to authenticated using (private.has_tenant_role(id, ARRAY['OWNER'::text, 'ADMIN'::text])) with check (private.has_tenant_role(id, ARRAY['OWNER'::text, 'ADMIN'::text]));

